class Solution:
    def maximumLength(self, s: str) -> int:
        from collections import defaultdict
        
        # Count occurrences of each special substring
        counts = defaultdict(int)
        n = len(s)
        
        for i in range(n):
            for j in range(i + 1, n + 1):
                sub = s[i:j]
                if len(set(sub)) == 1:  # special substring
                    counts[sub] += 1
        
        result = -1
        for sub, cnt in counts.items():
            if cnt >= 3:
                result = max(result, len(sub))
        
        return result
